# If a 4x4 window has diverse numbers (4+ unique non-1), the position is "uncertain" -> 1
# Otherwise, use most frequent non-1 in that window

def compute_output_v2(grid, window_size=4):
    rows = len(grid)
    cols = len(grid[0])
    output = [[1 for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            # Take window: rows[r-window:r+window+1], cols[c-window:c+window+1]
            window_rows = max(0, r-window)
            window_r = min(rows-1, r+window)
            window_cols = max(0, c-window)
            window_c = min(cols-1, c+window)

            window_grid = set()
            for rr in range(window_r - window_rows + 1):
                for cc in range(window_c - window_cols + 1):
                    val = grid[rr + window_rows][cc + window_cols]
                    if val != 1:
                        window_grid.add(val)

            # If too diverse, output 1 (uncertain)
            if len(window_grid) >= 4:
                output[r][c] = 1
            else:
                # Most frequent non-1
                counts = {}
                for rr in range(window_r - window_rows + 1):
                    for cc in range(window_c - window_cols + 1):
                        val = grid[rr + window_rows][cc + window_cols]
                        if val != 1:
                            counts[val] = counts.get(val, 0) + 1
                if counts:
                    output[r][c] = max(counts, key=counts.get)

    return output

